export const createBlankDay = (dayNumber: number, dateStr = '', destination?: string): ItineraryDay => {
  const defaultImg = getDefaultDayImage(destination, dayNumber);
  return {
    id: `d${dayNumber}-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`,
    dayNumber,
    date: dateStr,
    title: '',
    description: '',
    sightseeingHighlights: [],
    nightStay: '',
    mealPlan: 'Breakfast & Dinner',
    transportDetails: '',
    imageUrl: defaultImg.url,
    imageCaption: defaultImg.caption,
  };
};

export const createBlankItineraryFromLead = (lead: Lead): Itinerary => {
  const randomSuffix = Math.floor(1000 + Math.random() * 9000);
  const quoteNumber = `NED-${new Date().getFullYear()}-${randomSuffix}`;
  const dayCount = Math.max(1, lead.durationDays || 1);
  const nightCount =
    lead.durationNights !== undefined && lead.durationNights !== null
      ? lead.durationNights
      : Math.max(0, dayCount - 1);

  const defaultCover = getDefaultDestinationCover(lead.destination, lead.destination ? `${lead.destination} Tour Package` : '');

  // Generate blank day sections strictly as per lead data duration with predefined destination imagery
  const blankDays: ItineraryDay[] = Array.from({ length: dayCount }, (_, idx) => {
    const dayNum = idx + 1;
    let dayDate = '';
    if (lead.travelStartDate) {
      try {
        const d = new Date(lead.travelStartDate);
        d.setDate(d.getDate() + idx);
        dayDate = d.toISOString().split('T')[0];
      } catch {
        dayDate = '';
      }
    }
    const defaultDayImg = getDefaultDayImage(lead.destination, dayNum);
    return {
      id: `d${dayNum}-${Date.now()}-${idx}`,
      dayNumber: dayNum,
      date: dayDate,
      title: '', // Clean blank title for user to enter
      description: '', // Clean blank description
      sightseeingHighlights: [], // Clean blank highlights
      nightStay: '', // Clean blank night stay
      mealPlan: 'Breakfast & Dinner',
      transportDetails: '', // Clean blank cab details
      imageUrl: defaultDayImg.url,
      imageCaption: defaultDayImg.caption,
    };
  });

  return {
    id: `itin-${Date.now()}`,
    quoteNumber,
    title: lead.destination ? `${lead.destination} Tour Package` : '',
    destination: lead.destination || '',
    heroImageUrl: defaultCover.url,
    heroImageCaption: defaultCover.caption,
    leadId: lead.id,
    guestName: lead.guestName || '',
    guestPhone: lead.phone || '',
    guestEmail: lead.email || '',
    guestCity: lead.city || '',
    adults: lead.adults || 2,
    children: lead.children || 0,
    infants: lead.infants || 0,
    travelStartDate: lead.travelStartDate || '',
    travelEndDate: lead.travelEndDate || '',
    durationDays: dayCount,
    durationNights: nightCount,
    pickupLocation: '',
    dropLocation: '',
    hotelCategory: 'Deluxe Category (3-Star Mountain View)',
    mealPlan: 'MAP (Daily Breakfast & Dinner)',
    pricingMode: lead.preferredCab === 'both' ? 'both' : lead.preferredCab === 'sharing' ? 'sharing' : 'both',
    reservedCab: {
      enabled: true,
      name: 'Option A: Reserved Cab Facility (Private Dedicated SUV)',
      vehicleType: 'Innova / Xylo',
      description: 'Exclusive private SUV allocated strictly for your group from pickup to drop. Complete comfort, flexibility, and hotel doorstep convenience.',
      pricePerPerson: 0,
      totalPackagePrice: 0,
      gstPercentage: 0,
      gstIncluded: true,
      specificInclusions: [
        'Exclusive private Innova / Xylo allocated for your tour party only',
        'Hotel porch door-to-door pickup & drop for all excursions',
        'Driver mountain allowance, fuel, toll taxes, and parking fees',
      ],
      specificExclusions: [
        'Vehicle not on disposal for unannounced personal night outings',
      ],
    },
    sharingCab: {
      enabled: true,
      name: 'Option B: Sharing Cab Facility (Economical Shared Mountain Vehicle)',
      vehicleType: 'Tata Sumo / Mahindra Bolero',
      description: 'Budget-conscious shared vehicle facility between major taxi hubs. Fixed departure schedule.',
      pricePerPerson: 0,
      totalPackagePrice: 0,
      gstPercentage: 0,
      gstIncluded: true,
      specificInclusions: [
        'Seat allocation in shared Tata Sumo / Bolero on scheduled departure slots',
        'Standard route transfers between designated taxi hub terminals',
        'All driver mountain allowances and route toll taxes',
      ],
      specificExclusions: [
        'Local small taxi from terminal stand to interior uphill hotel',
        'Luggage exceeding standard 1 trolley bag per person',
      ],
    },
    sellingCost: 0,
    packageCost: 0,
    markupPercentage: 0,
    totalTransportCost: 0,
    totalHotelCost: 0,
    totalActivitiesCost: 0,
    days: blankDays,
    commonInclusions: [...defaultPackageInclusions],
    commonExclusions: [...defaultPackageExclusions],
    specialAdvisories: getDestinationSpecialAdvisories(lead.destination, lead.destination ? `${lead.destination} Tour Package` : ''),
    termsAndConditions: getDestinationTermsAndConditions(lead.destination, lead.destination ? `${lead.destination} Tour Package` : ''),
    cancellationRefundPolicy: getDestinationCancellationPolicy(lead.destination, lead.destination ? `${lead.destination} Tour Package` : ''),
    paymentMilestones: [...defaultPaymentMilestones],
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
};

